steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { issues(first: 50, query: \"Renew SSO certificate\") { nodes { id identifier title priority assignee { id name email type } creator { id name email type } team { name } } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { issues(first: 100) { nodes { id identifier title priority assignee { id name email } creator { id name email } } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "mutation { issueUpdate(id: \"i-it-sso\", input: { priority: 1 }) { id identifier title priority success } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "mutation { issueUpdate(id: \"i-it-sso\", input: { priority: 1 }) { success issue { id identifier title priority } } }"
  }'
